def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    previous = json.loads((PREVIOUS / 'prompts.json').read_text(encoding='utf8'))
    shared = previous['references']
    common = COMMON.replace('The user rejected the last concepts for looking like a clean civilian freighter with different paint.',
                            'The user liked the previous structural Junker concepts and requests twenty MORE distinct variations in that direction.')
    common = common.replace('Freely redesign its overly tidy outer hull plating and bracing in the direction specified below.',
                            'This reference already has accepted Junker character. Preserve that character while genuinely recomposing large hull forms, armour outlines, braces and functional salvage attachments in the new direction below. Do not simply replicate the previous variant or shuffle surface details.')
    variants = []
    for label, base, group, title, direction in VARIANTS:
        target = PREVIOUS / f'rh_freighter_{base}4_sheet.png'
        variants.append(dict(id=label, label=label, base_variant=base+'4', group_ru=group,
                             title_ru=title, target_image=target.as_posix(), target_sha256=sha(target),
                             prompt=common + direction + '\nMain title exactly: "RH JUNKER FREIGHTER / ' + label + '".'))
    payload = dict(tool='built-in image_gen', target='rh_freighter_pir',
                   latest_brief='Twenty additional structurally distinct Junker/pirate variants around original-scale RH freighter, immutable cabin, high hump, three flight views, six retractable side drums, no wings.',
                   source_cmp=previous['source_cmp'], source_sha256=previous['source_sha256'],
                   native_flight_dimensions_xyz=previous['native_flight_dimensions_xyz'],
                   references=shared, variants=variants)
    assert len(variants) == 20
    for ref in shared:
        assert sha(Path(ref['path'])) == ref['sha256']
    OUT.mkdir(parents=True, exist_ok=True)
    path = OUT / 'prompts.json'
    if path.exists():
        raise FileExistsError(path)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf8')
    print(path)


if __name__ == '__main__':
    main()
